package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class PlatformBrandingIT extends SiteProjectSupport {
 static final String SETTINGS="/api/console/settings/branding";
 JsonNode ok(ResponseEntity<JsonNode> r){assertThat(r.getStatusCode()).as("%s",r.getBody()).isEqualTo(HttpStatus.OK);return r.getBody().path("data");}
 JsonNode current(String t){return ok(request("GET",SETTINGS,t,null,null));}
 Map<String,Object> body(int version,String name,String logo){return Map.of("systemName",name,"logoUrl",logo,"faviconUrl","/icon.svg","footerText","公开平台页脚","version",version);}
 JsonNode save(String t,Map<String,Object> b,String k){return ok(request("PUT",SETTINGS,t,k,b));}
 void tenantBrand(Fixture f){jdbc.update("INSERT INTO cfg_tenant_setting(id,tenant_id,setting_key,value_type,setting_value) VALUES(?,?,'branding.systemName','STRING','租户自己的品牌')",f.tenant(),f.tenant());}
 @Test void publicWhitelistProtectedRealmAndTenantIndependence(){var f=fixture();tenantBrand(f);var pub=ok(http.getForEntity("/api/console/branding",JsonNode.class));assertThat(pub.properties()).extracting(Map.Entry::getKey).containsExactlyInAnyOrder("systemName","logoUrl","faviconUrl","footerText");assertThat(http.getForEntity(SETTINGS,JsonNode.class).getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);assertThat(request("GET",SETTINGS,tenantLogin(f,"pref-admin"),null,null).getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);assertThat(request("GET",SETTINGS,login(false),null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);String t=login(true);int v=current(t).path("version").asInt();var saved=save(t,body(v,"化工平台","http://127.0.0.1:18080/logo.png"),"public-"+v);assertThat(saved.path("version").asInt()).isEqualTo(v+1);assertThat(ok(http.getForEntity("/api/console/branding",JsonNode.class))).isEqualTo(saved.path("branding"));assertThat(jdbc.queryForObject("SELECT setting_value FROM cfg_tenant_setting WHERE tenant_id=? AND setting_key='branding.systemName'",String.class,f.tenant())).isEqualTo("租户自己的品牌");}
 @Test void exactReplayAndChangedBodyStaleRevisionAndValidation(){String t=login(true);int v=current(t).path("version").asInt();String key="brand-idem-"+v;var b=body(v,"可追踪品牌","/logo.svg");var first=save(t,b,key);assertThat(save(t,b,key)).isEqualTo(first);assertThat(request("PUT",SETTINGS,t,key,body(v,"不同内容","/logo.svg")).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(request("PUT",SETTINGS,t,UUID.randomUUID().toString(),b).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE action='PLATFORM_BRANDING_UPDATE' AND JSON_UNQUOTE(JSON_EXTRACT(after_summary,'$.systemName'))='可追踪品牌'",Integer.class)).isOne();for(String url:List.of("javascript:alert(1)","data:image/svg+xml,x","//evil.test/img","https://user:pass@example.com/x","/\\evil","/x\ny")){assertThat(request("PUT",SETTINGS,t,UUID.randomUUID().toString(),body(v+1,"无效图片",url)).getStatusCode()).as(url).isEqualTo(HttpStatus.BAD_REQUEST);}assertThat(request("PUT",SETTINGS,t,"negative",body(-1,"版本错误","")).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);assertThat(request("PUT",SETTINGS,t,"too-long",body(v+1,"x".repeat(101),"")).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);var missing=new HashMap<>(body(v+1,"缺版本",""));missing.remove("version");assertThat(request("PUT",SETTINGS,t,"missing",missing).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);assertThat(save(t,Map.of("systemName","恢复文字","logoUrl","","faviconUrl","","footerText","","version",v+1),"clear-"+v).path("branding").path("logoUrl").asText()).isEmpty();}
 @Test void auditFailureRollsBackThenConcurrentWritersHaveOneWinner()throws Exception{String t=login(true);int v=current(t).path("version").asInt();var before=current(t);String key="rollback-"+v;trigger("CREATE TRIGGER branding_fail BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='PLATFORM_BRANDING_UPDATE' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='branding audit test'; END IF; END");try{assertThat(request("PUT",SETTINGS,t,key,body(v,"回滚品牌","/logo.svg")).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);}finally{trigger("DROP TRIGGER branding_fail");}assertThat(current(t)).isEqualTo(before);var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await();return request("PUT",SETTINGS,t,key,body(v,"回滚品牌","/logo.svg")).getStatusCode().value();});var b=pool.submit(()->{gate.await();return request("PUT",SETTINGS,t,"other-"+v,body(v,"并发品牌","/logo.svg")).getStatusCode().value();});gate.countDown();assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}assertThat(current(t).path("version").asInt()).isEqualTo(v+1);}
 @Test void viewOnlyAccountCannotWriteAndRevocationStopsReplay(){consoleUsers();jdbc.update("INSERT INTO plt_role(id,role_code,role_name,status) VALUES(799001,'BRAND_READER','品牌只读','ACTIVE')");jdbc.update("INSERT INTO plt_role_permission(role_id,permission_id) VALUES(799001,1126)");jdbc.update("INSERT INTO plt_user(id,username,display_name,password_hash,status,force_password_change) VALUES(799002,'brand-reader','品牌只读',?,'ACTIVE',0)",passwords.encode("Console#Pass123"));jdbc.update("INSERT INTO plt_user_role(user_id,role_id) VALUES(799002,799001)");String read=ok(http.postForEntity("/api/console/auth/login",Map.of("username","brand-reader","password","Console#Pass123","deviceId","brand-read"),JsonNode.class)).path("accessToken").asText();assertThat(current(read).path("canManage").asBoolean()).isFalse();assertThat(request("PUT",SETTINGS,read,"reader-denied",body(current(read).path("version").asInt(),"越权","")).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);String t=login(true);int v=current(t).path("version").asInt();var b=body(v,"撤权前","/logo.svg");save(t,b,"before-revoke");jdbc.update("DELETE FROM plt_role_permission WHERE role_id=1001 AND permission_id=1127");try{assertThat(request("PUT",SETTINGS,t,"before-revoke",b).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}finally{jdbc.update("INSERT INTO plt_role_permission(role_id,permission_id) VALUES(1001,1127)");}}
}
